      SUBROUTINE UPDAT3CC     UPDATE R3 MATRIX (USED IN FITTING)CC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'CC     PRELIMINARY CALCULATIONC      IF (NORD2 .LT. 1) GO TO 300CC     CUMULATIVE R2 MATRIXC  100 CALL MR3R2CC     R3 TIMES DERIVATIVE OF R2C  200 IF (NV1 .GE. 1) THEN        DO 220 N = 1, NV1        IF (R2VP(N)) CALL MR3R2V(N)  220   CONTINUE      ENDIFC  300 R2P = R2P .OR. R3P      R3P = .FALSE.      RETURN      END